#!/bin/sh
# fork-push: push the fork-only branches of my personal GitHub forks to their Radicle projects.
# Generated by tools/forkpush.om from stack/FORKS.tsv; do not edit by hand.
#
# For every stack/FORKS.tsv row whose action is radicle, it fetches the branch from
# https://github.com/<owner>/<repo> into a Radicle working copy of the project, checks that the
# fetched commit is the head the manifest names, and only then pushes it to Radicle as
# fork/<branch>. Rows kept private and rows already in this repository are listed below as
# comments and are never fetched or pushed.
#
# Needs git, and rad authenticated as the project's delegate with its node running
# (rad auth, rad node start). It refuses to run as root.
#   FP_DIR=path  the one directory it creates and works in (default ./fork-push); each project
#                is cloned there once, into a directory named after its RID without rad:
# Exit status: 0 every branch OK, 2 a fetched commit is not the manifest head,
# 3 a clone, fetch or push failed (3 wins over 2).
# Manifest: 3 to push to Radicle, 1 kept private, 1 in this repository.

set -eu
umask 022

FP_DIR="${FP_DIR:-./fork-push}"
fp_say() { printf '%s\n' "$*"; }
fp_die() { printf 'fork-push: %s\n' "$*" >&2; exit 1; }

if [ "$(id -u)" = "0" ]; then fp_die "refusing to run as root; run it as your own user"; fi
command -v git >/dev/null 2>&1 || fp_die "git is required: https://git-scm.com"
command -v rad >/dev/null 2>&1 || fp_die "rad is required: https://radicle.xyz"
mkdir -p -- "$FP_DIR"
cd -- "$FP_DIR"
fp_ok=0
fp_bad=0
fp_fail=0

fp() {
  fp_d="${1#rad:}"
  if [ ! -d "$fp_d" ]; then
    if ! rad clone "$1" "$fp_d" </dev/null; then
      fp_say "FAILED    $1 rad clone"
      fp_fail=$((fp_fail + 1))
      rm -rf -- "./$fp_d"
      return 0
    fi
  fi
  if ! git -C "$fp_d" fetch --no-tags --quiet "https://github.com/$2" "+refs/heads/$3:refs/heads/fork/$3" </dev/null; then
    fp_say "FAILED    $1 fork/$3 fetch from https://github.com/$2"
    fp_fail=$((fp_fail + 1))
    return 0
  fi
  fp_got="$(git -C "$fp_d" rev-parse "refs/heads/fork/$3" 2>/dev/null || true)"
  if [ "$fp_got" != "$4" ]; then
    fp_say "MISMATCH  $1 fork/$3 manifest $4, fetched ${fp_got:-none}"
    fp_bad=$((fp_bad + 1))
    return 0
  fi
  if git -C "$fp_d" push --quiet rad "refs/heads/fork/$3:refs/heads/fork/$3" </dev/null; then
    fp_say "OK        $1 fork/$3 $4"
    fp_ok=$((fp_ok + 1))
  else
    fp_say "FAILED    $1 fork/$3 push"
    fp_fail=$((fp_fail + 1))
  fi
}

fp 'rad:zAAAA1111' 'me/alpha' 'feat/one' '0123456789abcdef0123456789abcdef01234567'
# private, kept off Radicle: me/alpha fix/crypto-x
fp 'rad:zAAAA1111' 'me/alpha' 'docs/v1.2_x' 'fedcba9876543210fedcba9876543210fedcba98'
# in this repository at docs/site: me/beta.site main
fp 'rad:zBBBB2222' 'me/gamma-1' 'node-8d75/run_2' 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb'

fp_say ""
fp_say "Done in $(pwd): $fp_ok OK, $fp_bad MISMATCH, $fp_fail FAILED."
if [ "$fp_fail" -gt 0 ]; then exit 3; fi
if [ "$fp_bad" -gt 0 ]; then exit 2; fi
exit 0
